pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";
import {ClonesWithImmutableArgs} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C public c;

    function setUp() public {
        // deploy a minimal clone directly, passing different addresses for owner (index 0) and collateral (index 1)
        address creator = address(0x1234);
        ERC20 collat = ERC20(address(0x5678));
        ERC20 debtToken = ERC20(address(0x9abc));
        CoolerFactory factory = CoolerFactory(address(0xdef0));
        bytes memory data = abi.encodePacked(creator, address(collat), address(debtToken), address(factory));
        address implementation = address(new C());
        address payable clone = ClonesWithImmutableArgs.clone(implementation, data);
        c = C(clone);
    }

    function testFuzz_property() public {
        // General rule: owner() and collateral() MUST return different addresses because
        // the first immutable arg (creator) differs from the second (collateral).
        // The buggy M changes owner() offset to the collateral arg slot, making them equal.
        address ownerAddr = c.owner();
        address collatAddr = address(c.collateral());
        assertTrue(ownerAddr != collatAddr, "owner() should not equal collateral()");
    }
}

